CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, salon_id TEXT NOT NULL, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, role TEXT NOT NULL, password TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,csrf TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS consultations(id TEXT PRIMARY KEY,salon_id TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS consultation_tenant ON consultations(salon_id);
CREATE TABLE IF NOT EXISTS resources(id TEXT PRIMARY KEY,consultation_id TEXT NOT NULL,kind TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS resource_parent ON resources(consultation_id);
CREATE TABLE IF NOT EXISTS presentations(id TEXT PRIMARY KEY,consultation_id TEXT NOT NULL,delivery_id TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(id TEXT PRIMARY KEY,hits INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,salon_id TEXT NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,resource TEXT NOT NULL,created_at TEXT NOT NULL);
